UPDATE "pages"
SET
  "title_en" = 'About Us',
  "title_ar" = 'من نحن',
  "meta_description_en" = 'SANAD is a career services brand helping professionals present their experience clearly, professionally, and effectively in the UAE job market.',
  "meta_description_ar" = 'سند علامة متخصصة في الخدمات المهنية، نساعد الباحثين عن عمل على عرض خبراتهم ومؤهلاتهم بصورة واضحة واحترافية تناسب سوق العمل في الإمارات.',
  "content_en" = $$
<h2>About Us</h2>
<p>SANAD is a career services brand focused on helping professionals present their experience clearly, professionally, and effectively in the UAE job market.</p>
<p>We provide practical career solutions that support different stages of the job-search process — from creating professional CVs and optimising LinkedIn profiles to preparing job application materials and supporting clients with targeted job outreach.</p>
<p>Our approach is simple: understand the client’s background, present their experience in the strongest relevant way, and provide clear, professional services designed around the realities of today’s recruitment process.</p>
<h2>What We Do</h2>
<p>SANAD provides professional career services designed to help job seekers improve how they present themselves and approach the job market.</p>
<p>Our services include professional CV writing in Arabic and English, LinkedIn profile optimisation, cover letters within selected packages, and a practical UAE Job Application Guide that explains how to search, apply, follow up, and use major recruitment platforms effectively.</p>
<p>We also provide a Job Application Service, where we review the client’s CV, identify suitable companies and opportunities based on their experience, prepare a professional application email, and send their CV to up to 60 suitable companies using the client’s email account.</p>
<p>Our goal is to make the job-search process more organised, professional, and easier for the client to manage.</p>
$$,
  "content_ar" = $$
<h2>من نحن</h2>
<p>سند هي علامة متخصصة في الخدمات المهنية، نساعد الباحثين عن عمل على عرض خبراتهم ومؤهلاتهم بصورة واضحة واحترافية تناسب سوق العمل في الإمارات.</p>
<p>نقدم حلولًا عملية تدعم العميل في مراحل مختلفة من رحلة البحث عن وظيفة، بداية من إعداد السيرة الذاتية وتحسين حساب لينكدإن، وصولًا إلى تجهيز أدوات التقديم والمساعدة في الوصول إلى الشركات والفرص المناسبة.</p>
<p>نعتمد على أسلوب بسيط وواضح: نفهم خبرة العميل ومساره المهني، ثم نعرضها بأفضل صورة مناسبة، ونقدم خدمات عملية تساعده على التعامل مع عملية البحث والتقديم بشكل أكثر احترافية وتنظيمًا.</p>
<h2>ماذا نقدم؟</h2>
<p>تقدم سند مجموعة من الخدمات المهنية التي تساعد الباحث عن عمل على تحسين طريقة تقديم نفسه والتعامل مع سوق الوظائف بشكل أكثر احترافية.</p>
<p>تشمل خدماتنا إعداد السير الذاتية الاحترافية باللغتين العربية والإنجليزية، وتحسين حسابات لينكدإن، وإعداد خطابات التقديم ضمن الباقات المختارة، بالإضافة إلى دليل التقديم على الوظائف في الإمارات الذي يشرح طرق البحث والتقديم والمتابعة واستخدام أهم منصات التوظيف.</p>
<p>كما نقدم خدمة التقديم على الوظائف، حيث نراجع السيرة الذاتية للعميل، ونبحث عن الشركات والفرص المناسبة لخبراته، ونجهز رسالة تقديم احترافية، ثم نرسل سيرته الذاتية إلى ما يصل إلى 60 شركة مناسبة باستخدام بريده الإلكتروني.</p>
<p>هدفنا هو جعل رحلة البحث عن وظيفة أكثر تنظيمًا واحترافية وأسهل على العميل.</p>
$$,
  "updated_at" = NOW()
WHERE "slug" = 'about-us';
